mapper.insert:
INSERT INTO product_reviews (
    product_id, user_id, order_id, rating, content, images, reply, status, created_at, updated_at
) VALUES (
    #{productId}, #{userId}, #{orderId}, #{rating}, #{content}, #{images}, #{reply}, #{status}, NOW(), NOW()
)

mapper.select:
SELECT *
FROM product_reviews
WHERE product_id = #{productId}
  AND status = 'VISIBLE'
ORDER BY created_at DESC
    LIMIT #{offset}, #{size}

mapper.update:
UPDATE product_reviews
SET status = #{status}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, product_id AS productId, user_id AS userId, order_id AS orderId,
       rating, content, images, reply, status,
       created_at AS createdAt, updated_at AS updatedAt
FROM product_reviews

    AND user_id = #{userId}
    AND order_id = #{orderId}
    AND product_id = #{productId}
    AND rating = #{rating}
    AND status = #{status}

ORDER BY created_at DESC

mapper.update:
UPDATE product_reviews
SET reply = #{reply}, updated_at = NOW()
WHERE id = #{id}
